package com.narratiaa.catalog;

import tools.jackson.databind.*;import com.narratiaa.auth.AuthService;import com.narratiaa.common.ApiException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.net.*;import java.net.http.*;import java.util.*;

@RestController @RequestMapping("/api/catalog")
public class CatalogController {
  private final AuthService auth;private final ObjectMapper json;public CatalogController(AuthService a,ObjectMapper j){auth=a;json=j;}
  @GetMapping("/search")Map<String,Object> search(HttpServletRequest req,@RequestParam String q){auth.requireUser(req);String query=q.trim();if(query.length()<2)throw new ApiException(HttpStatus.BAD_REQUEST,"Enter at least 2 characters.");try{String url="https://openlibrary.org/search.json?q="+URLEncoder.encode(query,java.nio.charset.StandardCharsets.UTF_8)+"&limit=10&lang=en&fields=key,title,author_name,cover_i,number_of_pages_median,subject,first_publish_year";var request=HttpRequest.newBuilder(URI.create(url)).header("User-Agent","Narratiaa/1.0 (reader application)").GET().build();var response=HttpClient.newHttpClient().send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200)throw new Exception();JsonNode docs=json.readTree(response.body()).path("docs");var results=new ArrayList<Map<String,Object>>();for(JsonNode d:docs){var b=new LinkedHashMap<String,Object>();b.put("externalId",d.path("key").asText());b.put("title",d.path("title").asText());b.put("author",d.path("author_name").path(0).asText("Unknown author"));b.put("genre",d.path("subject").path(0).asText(""));b.put("description",d.has("first_publish_year")?"First published in "+d.path("first_publish_year").asText()+".":"");b.put("coverUrl",d.has("cover_i")?"https://covers.openlibrary.org/b/id/"+d.path("cover_i").asText()+"-M.jpg":"");b.put("totalPages",d.path("number_of_pages_median").asInt(300));results.add(b);}return Map.of("results",results);}catch(Exception e){throw new ApiException(HttpStatus.BAD_GATEWAY,"Book search is temporarily unavailable.");}}
}
